macro.command:
// Mass Heal — apportion up to 700 HP of healing among targets
const totalPool = 700;
const targets = Array.from(workflow.targets);
const validTargets = targets.filter(t => {
  const type = t.actor?.system?.details?.type?.value?.toLowerCase() ?? "";
  return type !== "undead" && type !== "construct";
});
if (!validTargets.length) {
  ui.notifications.warn("Mass Heal: No valid targets (undead and constructs are unaffected).");
  return;
}
const data = validTargets.map((t, i) => {
  const hp = t.actor.system.attributes.hp;
  return { token: t, name: t.name, i, missing: Math.max(0, hp.max - hp.value), max: hp.max, current: hp.value };
});
let formContent = `<p>Distribute up to <strong>${totalPool}</strong> HP of healing. Remaining: <strong><span id="mh-pool">${totalPool}</span></strong></p>`;
formContent += "<table style='width:100%'><tr><th style='text-align:left'>Target</th><th>HP</th><th>Missing</th><th style='text-align:center'>Heal</th></tr>";
for (const d of data) {
  formContent += `<tr><td>${d.name}</td><td style='text-align:center'>${d.current}/${d.max}</td><td style='text-align:center'>${d.missing}</td>`;
  formContent += `<td><span style='display:inline-flex;align-items:center;gap:4px;justify-content:center;width:100%'>`;
  formContent += `<button type="button" class="mh-adj" data-idx="${d.i}" data-dir="-1" style="width:24px;height:24px;padding:0;line-height:24px;text-align:center;font-weight:bold;flex-shrink:0;">&minus;</button>`;
  formContent += `<input type="number" name="h${d.i}" value="${d.missing}" min="0" max="${d.missing}" data-max="${d.missing}" style="width:55px;text-align:center">`;
  formContent += `<button type="button" class="mh-adj" data-idx="${d.i}" data-dir="1" style="width:24px;height:24px;padding:0;line-height:24px;text-align:center;font-weight:bold;flex-shrink:0;">+</button>`;
  formContent += `</span></td></tr>`;
}
formContent += "</table>";
const { DialogV2 } = foundry.applications.api;
const formValues = await DialogV2.wait({
  window: { title: "Mass Heal" },
  content: formContent,
  rejectClose: false,
  render: (event, el) => {
    const form = el.querySelector ? el : el.element;
    const updatePool = () => {
      let used = 0;
      form.querySelectorAll('input[type=number]').forEach(inp => { used += parseInt(inp.value) || 0; });
      const poolEl = form.querySelector('#mh-pool');
      if (poolEl) poolEl.textContent = String(totalPool - used);
    };
    form.querySelectorAll('input[type=number]').forEach(inp => {
      inp.addEventListener('change', () => {
        const max = parseInt(inp.dataset.max) || 0;
        inp.value = Math.max(0, Math.min(max, parseInt(inp.value) || 0));
        updatePool();
      });
      inp.addEventListener('input', () => {
        const max = parseInt(inp.dataset.max) || 0;
        inp.value = Math.max(0, Math.min(max, parseInt(inp.value) || 0));
        updatePool();
      });
    });
    form.querySelectorAll('.mh-adj').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.preventDefault();
        const idx = btn.dataset.idx;
        const dir = parseInt(btn.dataset.dir);
        const inp = form.querySelector(`[name=h${idx}]`);
        const max = parseInt(inp.dataset.max) || 0;
        inp.value = Math.max(0, Math.min(max, (parseInt(inp.value) || 0) + dir));
        updatePool();
      });
    });
    updatePool();
  },
  buttons: [
    { action: "heal", label: "Heal", default: true, callback: (event, button, dialog) => {
      const result = {};
      const form = button.form;
      form.querySelectorAll('input[type=number]').forEach(inp => { result[inp.name] = parseInt(inp.value) || 0; });
      return result;
    }},
    { action: "cancel", label: "Cancel" }
  ]
});
if (!formValues) return;
let pool = totalPool;
const targetDamages = [];
for (const d of data) {
  let heal = Math.min(formValues[`h${d.i}`] || 0, d.missing, pool);
  if (heal <= 0) continue;
  pool -= heal;
  targetDamages.push({token: d.token, damageDetail: [{value: heal, type: "healing", properties: new Set(["mgc"])}], totalDamage: -heal});
  await d.token.actor.toggleStatusEffect("blinded", { active: false });
  await d.token.actor.toggleStatusEffect("deafened", { active: false });
}
if (targetDamages.length) {
  await MidiQOL.applyTokenDamageMany(targetDamages, workflow.item, {workflow, forceApply: true});
}
